"use client";

import { useState } from "react";
import type { components } from "@/lib/api-schema";
import { human, References } from "./evidence-views";

type Analysis = components["schemas"]["AnalysisOut"];
type Extraction = components["schemas"]["Extraction"];
type Claim = components["schemas"]["Assertion"];

export function EvidenceLedgerView({
  run,
  onSource,
}: {
  run: Analysis;
  onSource: (revision: string, span: string) => void;
}) {
  const [view, setView] = useState("sources");
  const [query, setQuery] = useState("");
  const ledger = run.result?.evidence_ledger;
  if (!ledger) return null;
  const citations = run.result?.citations ?? [];
  const count = ledger.extractions.reduce((n, x) => n + x.claims.length, 0);
  const proposals = [
    ...(ledger.reconciliation?.resolution_proposals ?? []),
    ...(ledger.reconciliation?.link_proposals ?? []),
  ];
  const filename = (revision: string) =>
    run.result?.document_sources?.find((s) => s.revision_id === revision)
      ?.filename ?? revision;
  const refs = (x: Extraction, ids: string[]) =>
    x.evidence
      .filter((e) => ids.includes(e.evidence_id))
      .map((e) => e.locator.block_id);
  const allClaims = ledger.extractions.flatMap((x) =>
    x.claims.map((claim) => ({ x, claim })),
  );
  const renderClaim = (x: Extraction, claim: Claim) => (
    <article className="ledger-claim" key={claim.claim_id}>
      <span className="eyebrow">
        {human(claim.predicate.replaceAll(".", " · "))}
      </span>
      <p>{claim.value.raw}</p>
      <p className="muted-text">
        {claim.polarity === "negative"
          ? "Negative statement"
          : human(claim.polarity)}{" "}
        · {human(claim.epistemic_qualification)} · {human(claim.temporality)} ·{" "}
        {human(claim.attribution.basis)}
      </p>
      <details>
        <summary>Scope, typed value and evidence</summary>
        <p>
          Subject:{" "}
          {x.entities.find((e) => e.entity_id === claim.subject_ref)
            ?.source_label ?? "Document or section"}
        </p>
        <p>
          Section:{" "}
          {x.sections.find(
            (s) => s.section_id === claim.scope.source_section_ref,
          )?.label ?? "Unknown"}
        </p>
        {claim.scope.segment_ref && (
          <p>
            Segment:{" "}
            {human(
              x.segments.find((s) => s.segment_id === claim.scope.segment_ref)
                ?.purpose ?? "unknown",
            )}
          </p>
        )}
        <pre className="abstraction-json">
          {JSON.stringify({ value: claim.value, scope: claim.scope }, null, 2)}
        </pre>
        {x.evidence
          .filter((e) => claim.evidence_ids.includes(e.evidence_id))
          .map((e) => (
            <blockquote key={e.evidence_id}>{e.quote}</blockquote>
          ))}
        <References
          ids={refs(x, claim.evidence_ids)}
          citations={citations}
          onSource={onSource}
        />
      </details>
    </article>
  );
  return (
    <>
      <div className="abstraction-overview-stats">
        <div>
          <strong>{ledger.extractions.length}</strong>
          <span>independent document extractions</span>
        </div>
        <div>
          <strong>{count}</strong>
          <span>source claims</span>
        </div>
        <div>
          <strong>
            {
              ledger.decisions.filter((d) => d.status === "requires_review")
                .length
            }
          </strong>
          <span>proposals requiring review</span>
        </div>
      </div>
      <p className="draft-notice">
        Claims preserve each source’s account. Model proposals are separate from
        server decisions. Clinical totals remain withheld until the required
        encounter, segment and field decisions are accepted.
      </p>
      {ledger.limitations.length > 0 && (
        <section className="alert warning">
          <strong>Extraction or reconciliation needs attention</strong>
          {ledger.limitations.map((text, i) => (
            <p key={i}>{text}</p>
          ))}
        </section>
      )}
      <div className="abstraction-tabs" aria-label="Evidence views">
        {[
          ["sources", "By document"],
          ["findings", "Clinical findings"],
          ["decisions", `Proposals (${proposals.length})`],
          ["json", "Structured JSON"],
        ].map(([id, label]) => (
          <button
            key={id}
            aria-pressed={view === id}
            onClick={() => setView(id)}
          >
            {label}
          </button>
        ))}
      </div>
      {(view === "sources" || view === "findings") && (
        <label className="ledger-search">
          Find a claim
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="A symptom, assessment, treatment or document"
          />
        </label>
      )}
      {view === "sources" &&
        ledger.extractions.map((x) => {
          const claims = x.claims.filter((c) =>
            `${filename(x.document_version_id)} ${c.predicate} ${c.value.raw}`
              .toLowerCase()
              .includes(query.toLowerCase()),
          );
          if (query && !claims.length) return null;
          return (
            <details className="clinical-topic" key={x.document_version_id}>
              <summary>
                {filename(x.document_version_id)}{" "}
                <span className="count">
                  {claims.length} claims · {x.processing_status}
                </span>
              </summary>
              <button
                className="secondary"
                onClick={() => onSource(x.document_version_id, "")}
              >
                Open original source ↗
              </button>
              {x.coverage_gaps.map((g) => (
                <p className="alert warning" key={g.gap_id}>
                  {g.limitation}
                </p>
              ))}
              {x.issues.map((i) => (
                <p className="alert warning" key={i.issue_id}>
                  {i.consequence}
                </p>
              ))}
              {claims.map((c) => renderClaim(x, c))}
            </details>
          );
        })}
      {view === "findings" && (
        <>
          <p className="muted-text">
            Source statements, grouped by topic. Repeated or conflicting
            statements remain separate until reconciled.
          </p>
          {[
            "clinical.symptom",
            "clinical.finding",
            "clinical.function",
            "clinical.diagnosis",
            "clinical.action",
            "clinical.intervention",
            "clinical.plan",
            "assessment",
            "medication",
            "plan",
          ].map((prefix) => {
            const items = allClaims.filter(
              ({ claim }) =>
                claim.predicate.startsWith(prefix) &&
                `${claim.value.raw} ${claim.predicate}`
                  .toLowerCase()
                  .includes(query.toLowerCase()),
            );
            return items.length ? (
              <details className="clinical-topic" key={prefix}>
                <summary>
                  {human(prefix.replaceAll(".", " · "))}{" "}
                  <span className="count">{items.length}</span>
                </summary>
                {items.map(({ x, claim }) => renderClaim(x, claim))}
              </details>
            ) : null;
          })}
        </>
      )}
      {view === "decisions" && (
        <>
          {!ledger.reconciliation && (
            <p>
              No validated reconciliation result is available. Independent
              source claims are retained.
            </p>
          )}
          {proposals.map((p) => {
            const decision = ledger.decisions.find(
              (d) => d.proposal_id === p.proposal_id,
            );
            return (
              <details className="clinical-topic" key={p.proposal_id}>
                <summary>
                  {human("decision_kind" in p ? p.decision_kind : p.relation)} ·{" "}
                  {human(decision?.status ?? "proposed")}
                </summary>
                <p>{p.rationale}</p>
                <p className="muted-text">
                  Server: {decision?.reason ?? "Not accepted"}
                </p>
                {"alternatives" in p &&
                  p.alternatives.map((a, i) => (
                    <p key={i}>
                      Alternative: {a.value.raw} · {a.polarity} ·{" "}
                      {a.epistemic_qualification}
                    </p>
                  ))}
                <References
                  ids={ledger.extractions.flatMap((x) =>
                    refs(x, p.evidence_ids),
                  )}
                  citations={citations}
                  onSource={onSource}
                />
                <pre className="abstraction-json">
                  {JSON.stringify(p, null, 2)}
                </pre>
              </details>
            );
          })}
        </>
      )}
      {view === "json" && (
        <pre className="abstraction-json">
          {JSON.stringify(ledger, null, 2)}
        </pre>
      )}
    </>
  );
}
