"use client";

import { useState } from "react";
import type { components } from "@/lib/api-schema";
import { References, human } from "./evidence-views";

type Analysis = components["schemas"]["AnalysisOut"];
type Profile = components["schemas"]["DocumentProfile"];
type When = components["schemas"]["DocumentTime"];
type Axis = "history" | "service" | "ingestion";

const whenLabel = (when: When) =>
  `${when.date}${when.end_date ? ` – ${when.end_date}` : ""}${when.time ? ` · ${when.time}` : ""}${when.timezone ? ` (${when.timezone})` : when.time ? " (timezone not stated)" : ""}`;

export function DocumentTimeline({
  run,
  patientId,
  onSource,
}: {
  run: Analysis;
  patientId: string;
  onSource: (revision: string, span: string) => void;
}) {
  const [axis, setAxis] = useState<Axis>("history");
  const [filter, setFilter] = useState("");
  const catalog = run.result?.document_catalog;
  if (!catalog) return null;
  const sources = run.result?.document_sources ?? [];
  const citations = run.result?.citations ?? [];
  const sourceFor = (doc: Profile) =>
    sources.find((s) => s.revision_id === doc.revision_id);
  const docs = catalog.documents.filter((doc) =>
    [
      doc.title,
      sourceFor(doc)?.filename,
      doc.document_type,
      ...doc.contributors.map((p) => p.name),
      ...doc.signatures.map((s) => s.name),
    ]
      .join(" ")
      .toLowerCase()
      .includes(filter.toLowerCase()),
  );
  const rows = docs
    .flatMap((doc) => {
      const events: { label: string; when: When; citations: string[] }[] =
        axis === "ingestion"
          ? []
          : doc.dates
              .filter((event) =>
                axis === "service"
                  ? ["service", "measurement", "effective"].includes(event.kind)
                  : !["service", "measurement", "effective"].includes(
                      event.kind,
                    ),
              )
              .map((event) => ({
                label: `${human(event.kind)} · ${event.scope}`,
                when: event.when,
                citations: event.citations,
              }));
      if (axis === "history") {
        for (const signature of doc.signatures) {
          if (signature.when)
            events.push({
              label: `${human(signature.kind)} · ${signature.name}`,
              when: signature.when,
              citations: signature.citations,
            });
        }
      }
      if (axis === "ingestion") {
        const rawIngested = sourceFor(doc)?.ingested_at;
        const ingested = rawIngested
          ? new Date(rawIngested).toISOString()
          : undefined;
        return [
          {
            doc,
            sort: ingested ?? "9999",
            label: "Imported into this workspace",
            date: ingested
              ? `${ingested.slice(0, 10)} · ${ingested.slice(11, 19)} UTC`
              : "Import date unavailable",
            citations: [] as string[],
          },
        ];
      }
      if (!events.length)
        return [
          {
            doc,
            sort: "9999",
            label:
              axis === "service"
                ? "Service date not established"
                : "Document history date not established",
            date: "Undated",
            citations: [] as string[],
          },
        ];
      return events.map((event) => ({
        doc,
        sort: `${event.when.date}T${event.when.time ?? ""}`,
        label: event.label,
        date: whenLabel(event.when),
        citations: event.citations,
      }));
    })
    .sort(
      (a, b) =>
        a.sort.localeCompare(b.sort) || a.doc.title.localeCompare(b.doc.title),
    );

  return (
    <>
      <p className="draft-notice">
        Unreviewed document metadata · {catalog.documents.length} sources.
        Signatures are reported from the text, not authenticated. Repeated
        entries represent document history, not additional visits.
      </p>
      <div className="timeline-controls">
        <label>
          Timeline dates
          <select
            aria-label="Timeline dates"
            value={axis}
            onChange={(e) => setAxis(e.target.value as Axis)}
          >
            <option value="history">Document history</option>
            <option value="service">Clinical and effective dates</option>
            <option value="ingestion">Workspace import dates</option>
          </select>
        </label>
        <label>
          Find a document
          <input
            aria-label="Find a document"
            placeholder="Title, filename, author or signer"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
          />
        </label>
      </div>
      <p className="muted-text">
        {axis === "history"
          ? "Creation, entry, review, signature, receipt, posting and export dates. Dates without a stated time have no inferred order within that day."
          : axis === "service"
            ? "Service, questionnaire completion and plan effective dates. These do not all represent attended visits. One document may cover several dates."
            : "When each source revision first entered this workspace, from system records. These are not clinical or signature dates."}
      </p>
      {!rows.length && <p>No matching documents.</p>}
      <ol className="document-timeline">
        {rows.map((row, index) => (
          <li key={`${row.doc.revision_id}-${index}`}>
            <div className="timeline-date">
              <strong>{row.date}</strong>
              <span>{row.label}</span>
            </div>
            <article className="document-card">
              <span className="eyebrow">
                {human(row.doc.document_type)} ·{" "}
                {row.doc.stated_status ?? "Record status unknown"}
              </span>
              <h3>
                <button
                  onClick={() =>
                    onSource(
                      row.doc.revision_id,
                      row.citations[0] ?? row.doc.citations[0] ?? "",
                    )
                  }
                >
                  {row.doc.title} ↗
                </button>
              </h3>
              <p className="document-filename">
                {sourceFor(row.doc)?.filename}
              </p>
              <details className="document-evidence">
                <summary>
                  Document details · signatures{" "}
                  {human(row.doc.signature_status)}
                </summary>
                <p>
                  Authors:{" "}
                  {row.doc.contributors
                    .filter((p) => p.role === "author")
                    .map((p) => p.name)
                    .join("; ") || "Not established"}
                </p>
                {row.doc.contributors.some(
                  (person) => person.role !== "author",
                ) && (
                  <p>
                    {row.doc.contributors
                      .filter((person) => person.role !== "author")
                      .map((person) => `${human(person.role)}: ${person.name}`)
                      .join("; ")}
                  </p>
                )}
                {(row.doc.statuses ?? []).map((status, i) => (
                  <p key={`status-${i}`}>
                    {status.scope}: {status.value}
                  </p>
                ))}
                <p>
                  Signature status: {human(row.doc.signature_status)}
                  {row.doc.signatures.length > 0 &&
                    ` · ${row.doc.signatures.map((s) => `${s.name} (${human(s.kind)})`).join("; ")}`}
                </p>
                {row.doc.relations.map((rel, i) => (
                  <p className="document-relation" key={i}>
                    {human(rel.kind)}: {rel.target_description} · {rel.scope}
                    {rel.target_revision_id && (
                      <>
                        {" "}
                        <button
                          onClick={() => onSource(rel.target_revision_id!, "")}
                        >
                          Open related source ↗
                        </button>
                      </>
                    )}
                  </p>
                ))}
                <details className="document-evidence">
                  <summary>People, dates and supporting evidence</summary>
                  <References
                    ids={row.doc.citations}
                    citations={citations}
                    onSource={onSource}
                  />
                  {(row.doc.statuses ?? []).map((status, i) => (
                    <div key={`status-${i}`}>
                      <p>
                        {status.scope}: {status.value}
                      </p>
                      <References
                        ids={status.citations}
                        citations={citations}
                        onSource={onSource}
                      />
                    </div>
                  ))}
                  {row.doc.contributors.map((person, i) => (
                    <div key={`person-${i}`}>
                      <p>
                        {human(person.role)}: {person.name} · {person.scope}
                      </p>
                      <References
                        ids={person.citations}
                        citations={citations}
                        onSource={onSource}
                      />
                    </div>
                  ))}
                  {row.doc.signatures.map((signature, i) => (
                    <div key={`signature-${i}`}>
                      <p>
                        {human(signature.kind)}: {signature.name} ·{" "}
                        {signature.scope} ·{" "}
                        {signature.when
                          ? whenLabel(signature.when)
                          : "Date not stated"}
                      </p>
                      <References
                        ids={signature.citations}
                        citations={citations}
                        onSource={onSource}
                      />
                    </div>
                  ))}
                  {row.doc.dates.map((event, i) => (
                    <div key={`date-${i}`}>
                      <p>
                        {human(event.kind)}: {whenLabel(event.when)} ·{" "}
                        {event.scope}
                      </p>
                      <References
                        ids={event.citations}
                        citations={citations}
                        onSource={onSource}
                      />
                    </div>
                  ))}
                  {row.doc.relations.map((rel, i) => (
                    <div key={`relation-${i}`}>
                      <p>
                        Source-described relationship: {human(rel.kind)} ·{" "}
                        {rel.scope}
                      </p>
                      <References
                        ids={rel.citations}
                        citations={citations}
                        onSource={onSource}
                      />
                    </div>
                  ))}
                </details>
              </details>
            </article>
          </li>
        ))}
      </ol>
      {catalog.limitations.length > 0 && (
        <details className="coverage-details">
          <summary>Metadata gaps and limitations</summary>
          {catalog.limitations.map((value, i) => (
            <p key={i}>{value}</p>
          ))}
        </details>
      )}
      <details className="coverage-details">
        <summary>Inspect document JSON</summary>
        <pre className="abstraction-json">
          {JSON.stringify(
            {
              scope: { patient_id: patientId, snapshot_id: run.snapshot_id },
              extraction: {
                run_id: run.id,
                schema_version: run.schema_version,
                prompt_version: run.prompt_version,
                model: run.model,
                created_at: run.created_at,
                review_status: "unreviewed",
              },
              ...catalog,
              sources,
              citations,
            },
            null,
            2,
          )}
        </pre>
      </details>
    </>
  );
}
